function results = opf_case57_sc(branch_BR_R_41_42, bus_PD_8)
    define_constants;
    mpc = loadcase('case57');

    branch_idx_41_42 = find( ...
        (mpc.branch(:, F_BUS) == 41 & mpc.branch(:, T_BUS) == 42) | ...
        (mpc.branch(:, F_BUS) == 42 & mpc.branch(:, T_BUS) == 41) );
    r0_41_42 = mpc.branch(branch_idx_41_42, BR_R);
    assert(all(branch_BR_R_41_42 >= r0_41_42));
    mpc.branch(branch_idx_41_42, BR_R) = branch_BR_R_41_42;

    bus8_idx = find(mpc.bus(:, BUS_I) == 8);
    pd0_bus8 = mpc.bus(bus8_idx, PD);
    assert(bus_PD_8 <= pd0_bus8);
    mpc.bus(bus8_idx, PD) = bus_PD_8;

    mpopt = mpoption('opf.violation', 1e-8, 'model', 'DC');

    beta = 17;

    om = opf_setup(mpc, mpopt);

    nb = size(mpc.bus, 1);
    br_on = find(mpc.branch(:, BR_STATUS) == 1);
    nl = length(br_on);

    f = mpc.branch(br_on, F_BUS);
    t = mpc.branch(br_on, T_BUS);

    E = sparse(1:nl, f,  1, nl, nb) + sparse(1:nl, t, -1, nl, nb);

    Q_va = 2 * beta * (E' * E);
    om = om.add_quad_cost('ang_diff_pen', Q_va, [], 0, {'Va'});

    idx_i1 = om.var.idx.i1;
    idx_iN = om.var.idx.iN;

    [x, fval, eflag, ~, ~] = om.solve();

    Va_solution = x(idx_i1.Va:idx_iN.Va);
    Pg_solution = x(idx_i1.Pg:idx_iN.Pg);

    results = mpc;
    results.bus(:, VA) = Va_solution * 180/pi;
    results.gen(:, PG) = Pg_solution;
    results.f = fval;
    results.success = (eflag > 0);

end

