function results = opf_case118_sc(gen_QMAX_65, bus_PD_54)
    define_constants;
    mpc = loadcase('case118');

    gen65_idx = find(mpc.gen(:, GEN_BUS) == 65);
    qmax0_gen65 = mpc.gen(gen65_idx, QMAX);
    assert(all(gen_QMAX_65 <= qmax0_gen65));
    mpc.gen(gen65_idx, QMAX) = gen_QMAX_65;

    bus54_idx = find(mpc.bus(:, BUS_I) == 54);
    pd0_bus54 = mpc.bus(bus54_idx, PD);
    assert(bus_PD_54 >= pd0_bus54);
    mpc.bus(bus54_idx, PD) = bus_PD_54;

    mpopt = mpoption('opf.violation', 1e-7, 'model', 'AC', 'opf.ac.solver', 'MIPS');

    c_Q = [60; 40; 35];
    target_buses = [65 66 69];

    om = opf_setup(mpc, mpopt);

    idx_i1 = om.var.idx.i1;
    idx_iN = om.var.idx.iN;
    ng = idx_iN.Pg - idx_i1.Pg + 1;

    gen_buses = mpc.gen(:, GEN_BUS);
    c_Q_full = zeros(ng, 1);

    for i = 1:length(target_buses)
        idx = find(gen_buses == target_buses(i));
        if ~isempty(idx)
            c_Q_full(idx) = c_Q(i);
        end
    end

    Q_mat = sparse(1:ng, 1:ng, 2*c_Q_full, ng, ng);
    om = om.add_quad_cost('reactive_support_cost', Q_mat, [], 0, {'Qg'});

    [x, fval, eflag, ~, ~] = om.solve();

    Vm_solution = x(idx_i1.Vm:idx_iN.Vm);
    Va_solution = x(idx_i1.Va:idx_iN.Va);
    Pg_solution = x(idx_i1.Pg:idx_iN.Pg);
    Qg_solution = x(idx_i1.Qg:idx_iN.Qg);

    results = mpc;
    results.bus(:, VA) = Va_solution * 180/pi;
    results.bus(:, VM) = Vm_solution;
    results.gen(:, PG) = Pg_solution;
    results.gen(:, QG) = Qg_solution;
    results.f = fval;
    results.success = (eflag > 0);

end

