function results = opf_case14_sc(bus_PD_10)
    define_constants;
    mpc = loadcase('case14');

    bus10_idx = find(mpc.bus(:, BUS_I) == 10);
    pd0_bus10 = mpc.bus(bus10_idx, PD);
    assert(bus_PD_10 >= pd0_bus10);
    mpc.bus(bus10_idx, PD) = bus_PD_10;

    mpopt = mpoption('opf.violation', 1e-8, 'model', 'AC', 'opf.ac.solver', 'MIPS');

    beta = 5200;
    Vref_target = 1.0;

    om = opf_setup(mpc, mpopt);

    idx_i1 = om.var.idx.i1;
    idx_iN = om.var.idx.iN;
    nb = size(mpc.bus, 1);
    nv = om.var.N;

    Q = sparse(nv, nv);
    Q(idx_i1.Vm:idx_iN.Vm, idx_i1.Vm:idx_iN.Vm) = 2 * beta * speye(nb);

    Vref = Vref_target * ones(nb, 1);
