    assert(bus_PD_54 >= pd0_bus54);
    mpc.bus(bus54_idx, PD) = bus_PD_54;

    mpopt = mpoption('opf.violation', 1e-8, 'model', 'AC', 'opf.ac.solver', 'MIPS');

    beta = 6050;
    Vref_target = 1.0;

    om = opf_setup(mpc, mpopt);

    idx_i1 = om.var.idx.i1;
    idx_iN = om.var.idx.iN;
    nb = size(mpc.bus, 1);
    nv = om.var.N;

    Q = sparse(nv, nv);
    Q(idx_i1.Vm:idx_iN.Vm, idx_i1.Vm:idx_iN.Vm) = 2 * beta * speye(nb);

    Vref = Vref_target * ones(nb, 1);
    c = zeros(nv, 1);
    c(idx_i1.Vm:idx_iN.Vm) = -2 * beta * Vref;

    k = beta * sum(Vref.^2);

    om = om.add_quad_cost('voltage_penalty', Q, c, k);

    [x, fval, eflag, ~, ~] = om.solve();

    Vm_solution = x(idx_i1.Vm:idx_iN.Vm);
    Va_solution = x(idx_i1.Va:idx_iN.Va);
    Pg_solution = x(idx_i1.Pg:idx_iN.Pg);
    Qg_solution = x(idx_i1.Qg:idx_iN.Qg);

    results = mpc;
    results.bus(:, VA) = Va_solution * 180/pi;
    results.bus(:, VM) = Vm_solution;
    results.gen(:, PG) = Pg_solution;
    results.gen(:, QG) = Qg_solution;
    results.f = fval;
    results.success = (eflag > 0);

end

function results = opf_case118_sc(bus_PD_76)
    define_constants;
    mpc = loadcase('case118');

    bus76_idx = find(mpc.bus(:, BUS_I) == 76);
    pd0_bus76 = mpc.bus(bus76_idx, PD);
    assert(bus_PD_76 <= pd0_bus76);
    mpc.bus(bus76_idx, PD) = bus_PD_76;

    mpopt = mpoption('opf.violation', 1e-8, 'model', 'DC', 'opf.dc.solver', 'IPOPT');

    beta = 15;

    om = opf_setup(mpc, mpopt);

    nb = size(mpc.bus, 1);
    br_on = find(mpc.branch(:, BR_STATUS) == 1);
    nl = length(br_on);

    f = mpc.branch(br_on, F_BUS);
    t = mpc.branch(br_on, T_BUS);

    E = sparse(1:nl, f,  1, nl, nb) + sparse(1:nl, t, -1, nl, nb);

    Q_va = 2 * beta * (E' * E);
    om = om.add_quad_cost('ang_diff_pen', Q_va, [], 0, {'Va'});

    idx_i1 = om.var.idx.i1;
    idx_iN = om.var.idx.iN;

    [x, fval, eflag, ~, ~] = om.solve();

    Va_solution = x(idx_i1.Va:idx_iN.Va);
    Pg_solution = x(idx_i1.Pg:idx_iN.Pg);

    results = mpc;
    results.bus(:, VA) = Va_solution * 180/pi;
    results.gen(:, PG) = Pg_solution;
    results.f = fval;
    results.success = (eflag > 0);

end

function results = opf_case118_sc(branch_RATE_A_38_65)
    define_constants;
    mpc = loadcase('case118');

    branch_idx_38_65 = find( ...
        (mpc.branch(:, F_BUS) == 38 & mpc.branch(:, T_BUS) == 65) | ...
        (mpc.branch(:, F_BUS) == 65 & mpc.branch(:, T_BUS) == 38) );
    rate0_38_65 = mpc.branch(branch_idx_38_65, RATE_A);
    assert(all(branch_RATE_A_38_65 <= rate0_38_65));
    mpc.branch(branch_idx_38_65, RATE_A) = branch_RATE_A_38_65;

    mpopt = mpoption('opf.violation', 1e-8, 'model', 'DC');
    baseMVA = mpc.baseMVA;
    ng = size(mpc.gen, 1);

    SPmax_MW = 60;
    R_SP_MW = 102;
    SPmax_pu = SPmax_MW / baseMVA;
    R_SP_pu = R_SP_MW / baseMVA;

    om = opf_setup(mpc, mpopt);
    om.add_var('SP', ng, zeros(ng,1), zeros(ng,1), SPmax_pu*ones(ng,1));

    iPg = om.var.idx.i1.Pg : om.var.idx.iN.Pg;
    iSP = om.var.idx.i1.SP : om.var.idx.iN.SP;
    nv = om.var.N;

    A = sparse(ng, nv);
    A(:, iPg) = speye(ng);
    A(:, iSP) = speye(ng);
    u_pu = mpc.gen(:, PMAX) / baseMVA;
    om.add_lin_constraint('Pg_SP_le_Pmax', A, -inf(ng,1), u_pu);

    Areg = sparse(1, nv);
    Areg(1, iSP) = 1;
    om.add_lin_constraint('region_SP_req', Areg, R_SP_pu, inf(1,1));

    idx_i1 = om.var.idx.i1;
    idx_iN = om.var.idx.iN;

    [x, fval, eflag, ~, ~] = om.solve();

    Va_solution = x(idx_i1.Va:idx_iN.Va);
    Pg_solution = x(idx_i1.Pg:idx_iN.Pg);

    results = mpc;
    results.bus(:, VA) = Va_solution * 180/pi;
    results.gen(:, PG) = Pg_solution;
    results.f = fval;
    results.success = (eflag > 0);

end
